import{_ as r,o as s,c as e,a5 as t}from"./chunks/framework.QWVCgkrI.js";const d=JSON.parse('{"title":"同じシーンでVSyncオフ・オン・VRRを比べる","description":"","frontmatter":{"title":"同じシーンでVSyncオフ・オン・VRRを比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"graphics","collection":"vsync-vrr-observation","order":1,"summary":"同じ描画完了時刻から、走査中のティアリング、固定周期での再表示、VRRで次の走査を始める時刻を見比べる。","aliases":["VSync","VRR","可変リフレッシュレート","ティアリング","スキャンアウト","垂直ブランク"],"verification":"Vulkanの提示仕様、Linux DRM/KMSのVRR、DXGIの公式資料に照合（2026-11-13）"}},"headers":[],"relativePath":"practice/graphics/vsync-vrr-observation.md","filePath":"practice/graphics/vsync-vrr-observation.md"}'),i={name:"practice/graphics/vsync-vrr-observation.md"};function o(l,a,n,c,h,m){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="同じシーンでvsyncオフ・オン・vrrを比べる" tabindex="-1">同じシーンでVSyncオフ・オン・VRRを比べる <a class="header-anchor" href="#同じシーンでvsyncオフ・オン・vrrを比べる" aria-label="Permalink to &quot;同じシーンでVSyncオフ・オン・VRRを比べる&quot;">​</a></h1><p>横に動く物体を、3方式で同じ位置、同じ描画完了時刻から表示します。タイムラインで新しい絵を使う時刻を、仮想画面で上と下がどの画像に対応するかを見ます。<a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSyncの記事</a>で、それぞれの更新方法を図解しています。</p><p><a href="/study/samples/graphics/vsync-vrr-observation/index.html" target="_self">3方式の比較デモを開く</a></p><h2 id="_20-msで画面を止めて比べる" tabindex="-1">20 msで画面を止めて比べる <a class="header-anchor" href="#_20-msで画面を止めて比べる" aria-label="Permalink to &quot;20 msで画面を止めて比べる&quot;">​</a></h2><p><strong>20 msの例を見る</strong>を押して、次の順に切り替えます。描画フレームAは0 ms、Bは20 msに完成します。</p><ol><li><strong>VSyncオフ</strong>では、固定60 Hzの走査が約16.67 msにAから始まります。Bが20 msに完成し、走査の途中で絵が替わります。仮想画面では上約20%がA、下約80%がBです。動く物体の境目が横にずれます。</li><li><strong>VSyncオン</strong>では、約16.67 msにAをもう一度走査します。Bの走査は次の境界の約33.33 msからです。全行が同じ絵になり、物体はAの位置に長く残ります。</li><li><strong>VRR</strong>では、Bが完成した20 msに新しい走査が始まります。Bの走査は全行にBを使います。次の絵Cが40 msに完成するまで、Bの走査終了から次の走査までに待ちが入ります。</li></ol><h2 id="再生して、止まる箇所を比べる" tabindex="-1">再生して、止まる箇所を比べる <a class="header-anchor" href="#再生して、止まる箇所を比べる" aria-label="Permalink to &quot;再生して、止まる箇所を比べる&quot;">​</a></h2><p><strong>スロー再生</strong>で、物体が動く間隔を見ます。VSyncオフでは、走査中に絵が切り替わる箇所で物体の輪郭がずれます。固定VSyncオンでは、描画完了が固定周期の境界をまたぐと同じ絵を再表示します。このとき画面に残る長さが変わり、動きが一瞬止まったように見えます。VRRでは、今回の範囲内の描画完了を次の走査の開始に使います。</p><p><strong>仮想の時刻</strong>を <strong>38 ms</strong> 付近にすると、VRRではBの走査が終わり、Cの完成を待っています。<strong>次の描画完了へ</strong>を押すと、Cが完成して走査を始める <strong>40 ms</strong> に進みます。前の絵を残して待つ時間と、その絵を上から下へ読む時間をタイムラインで分けて見ます。</p><h2 id="この実践の条件" tabindex="-1">この実践の条件 <a class="header-anchor" href="#この実践の条件" aria-label="Permalink to &quot;この実践の条件&quot;">​</a></h2><ul><li>固定方式は60 Hzで、モデルの1回の走査は約16.67 msです。</li><li>VRRは仮想40〜60 Hzです。A〜Dの間隔は18〜20 msで、DからEは22 msです。サンプル全体では18〜22 msで、すべて仮想VRRの対応範囲内です。</li><li>ブラウザーは、仮想画面の1回分の走査結果とタイムラインを描きます。実際の画面の更新設定はOSやドライバーから変更します。物理ディスプレイでの見え方や可変範囲は機器によって異なります。</li></ul><p>更新方式をそろえて表示間隔だけを変える比較は、<a href="/study/practice/graphics/frame-pacing-observation.html">フレームペーシングの実践</a>で試せます。</p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>20 msのVSyncオフで、絵Bが画面の上側に出ないのはなぜですか。</p><details class="details custom-block"><summary>解答</summary><p>20 msまでに上側の行はAから読み出されています。その時点から下の行をBで読むので、境目にずれが見えます。</p></details></li><li><p>38 msのVRRで、Cの走査を始めるのを何が止めていますか。</p><details class="details custom-block"><summary>解答</summary><p>Cは40 msで完成します。38 msではBの走査を終え、前の絵を残した状態でCの完成を待っています。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a></li><li><a href="/study/practice/graphics/swap-chain-observation.html">FIFO・MAILBOX・IMMEDIATEの実践</a>で、画像を待ち行列に入れたり置き換えたりする違いを確認する。</li><li><a href="/study/learn/roadmap.html?node=gfx-optimization#graphics">3DCG・描画ロードマップの「GPU最適化」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPresentModeKHR.html" target="_blank" rel="noreferrer">Khronos — VkPresentModeKHR</a></li><li><a href="https://docs.kernel.org/6.14/gpu/drm-kms.html#variable-refresh-properties" target="_blank" rel="noreferrer">Linux DRM/KMS — Variable refresh properties</a></li><li><a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddxgi/variable-refresh-rate-displays" target="_blank" rel="noreferrer">Microsoft — Variable refresh rate displays</a></li></ul>',18)])])}const u=r(i,[["render",o]]);export{d as __pageData,u as default};
